{
    "predictors": [
        {
            "name": "Patent Growth Rate",
            "construction": "Annual growth rate of the number of patents filed by the firm, sourced from the US Patent and Trademark Office, over the past three years.",
            "rationale": "Firms with rapidly increasing patent filings may be innovating more aggressively, potentially leading to higher future profitability.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Executive Compensation Ratio",
            "construction": "CEO total compensation divided by the total compensation of the top five executives, using data from proxy statements in the last fiscal year.",
            "rationale": "A higher ratio may indicate a strong alignment of CEO incentives with shareholder interests, driving better firm performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Supplier Concentration Index",
            "construction": "The Herfindahl-Hirschman Index (HHI) of the firm's top five suppliers' revenue, sourced from annual reports.",
            "rationale": "Firms less dependent on a few suppliers may have more stable operations and better negotiation leverage.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Customer Satisfaction Score",
            "construction": "Annual average of customer satisfaction scores from surveys conducted by independent agencies for the last fiscal year.",
            "rationale": "High customer satisfaction may indicate strong customer loyalty and potential future revenue growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Environmental Violation Count",
            "construction": "Total number of environmental violations reported by the Environmental Protection Agency over the past five years.",
            "rationale": "Firms with fewer violations may face lower regulatory risks and associated costs.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Employee Turnover Ratio",
            "construction": "Annual voluntary turnover rate of employees, calculated from human resources reports.",
            "rationale": "Lower turnover can indicate employee satisfaction and operational stability.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "R&D Efficiency",
            "construction": "Research and development expenses divided by the number of successful product launches in the last three years.",
            "rationale": "Efficient R&D spending that leads to successful product launches may indicate effective innovation strategies.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Social Media Sentiment Score",
            "construction": "Average sentiment score of the firm's mentions on major online forums and social media platforms over the past six months, using text analysis tools.",
            "rationale": "Positive sentiment may reflect strong consumer approval and brand strength.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Board Diversity Index",
            "construction": "Proportion of board members from underrepresented groups, based on annual board composition disclosures.",
            "rationale": "Diverse boards may bring a wider range of perspectives, potentially leading to better decision-making and firm performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Adoption Speed of New Technology",
            "construction": "Time taken for a firm to adopt major new industry-specific technologies relative to its peers, measured in months.",
            "rationale": "Firms that quickly adopt new technologies may gain competitive advantages and operational efficiencies.",
            "higher_returns_for": "low values of the measure"
        }
    ]
}
